--
-- Tags and epics sort by heat (label-heat.ts): the rank is log2(heat) + half-lives since the epoch, a week per half-life,
-- so it decays without rewrites. The live tasks give every label in use its rank, so the list has an order from day one:
-- a task counts by how long ago it was created or moved, a started one double, an epic double; accepted tasks are done.
-- changedFields goes so the CDC worker attributes the write from the WAL diff, not from the label's last edit.
-- No RLS wrapper: the migrate role owns labels and RLS is not forced (10-rls side effect).
UPDATE "labels" AS l
SET "display_order" = ln(h.heat * (CASE WHEN l.mode = 'epic' THEN 2 ELSE 1 END)) / ln(2.0) + extract(epoch FROM now()) / 604800,
    "stx" = "stx" - 'changedFields'
FROM (
  SELECT lid AS id,
         sum((CASE WHEN t.status = 4 THEN 2 ELSE 1 END)
             * power(2, greatest(-1000, (extract(epoch FROM greatest(t.created_at, t.status_changed_at)) - extract(epoch FROM now())) / 604800))) AS heat
  FROM "tasks" AS t, unnest(t.labels) AS lid
  WHERE t.deleted_at IS NULL AND t.status <> 0
  GROUP BY lid
) AS h
WHERE l.id::text = h.id AND l.mode <> 'primary' AND l.deleted_at IS NULL AND l.display_order IS NULL;
